local AiBotOldSetPlayableArea = SetPlayableArea
SetPlayableArea = function(rect, voFlag)
    AiBotOldSetPlayableArea(rect, voFlag)
    ForkThread(ForkedPlayableAreaChange, rect, voFlag)
end

function ForkedPlayableAreaChange(rect, voFlag)
    --If run too early AiBot code wont have loaded
    if GetGameTimeSeconds() < 3 then
        WaitSeconds(3 - math.floor(GetGameTimeSeconds()))
    end
    if import('/lua/AiBot/AI/AiBotUtilities.lua').bAiBotAIInGame then
        local AiBotProfiler = import('/lua/AiBot/AI/AiBotProfiler.lua')
        local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
        local sFunctionRef = 'ForkedPlayableAreaChange'
        AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)
        if bDebugMessages == true then LOG(sFunctionRef..': rect='..repru(rect)..'; voFlag='..reprs(voFlag)) end
        ForkThread(import('/lua/AiBot/AI/AiBotEvents.lua').OnPlayableAreaChange, rect, voFlag)
        AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
    end
end

local AiBotOldCreatePlatoonDeathTrigger = CreatePlatoonDeathTrigger
CreatePlatoonDeathTrigger = function(callback, platoon)
    AiBotOldCreatePlatoonDeathTrigger(callback, platoon)
    local tUnits = platoon:GetPlatoonUnits()
    if tUnits then
        local AiBotEvents = import('/lua/AiBot/AI/AiBotEvents.lua')
        for iUnit, oUnit in tUnits do
            ForkThread(AiBotEvents.DeathTriggerAdded, oUnit)
        end
    end
end